// Assumed policy: both customers have inclusive 30-day annual and 14-day
// monthly refund windows. No company policy values were supplied.
exports.solve = (customer, plan, daysSincePurchase) => {
  if (!['Acme', 'Other'].includes(customer) ||
      !Number.isInteger(daysSincePurchase) || daysSincePurchase < 0) {
    return false;
  }
  if (plan === 'annual') return daysSincePurchase <= 30;
  if (plan === 'monthly') return daysSincePurchase <= 14;
  return false;
};

