const { validate } = require('./validate.cjs');
const service = require('./service.cjs');
exports.solve = request => {
  if (!validate(request)) {
    return { status: 400, body: { error: 'invalid request' } };
  }
  return { status: 200, body: { items: service.solve(request.items) } };
};
